// ============================================================================
// tb_decoder_top.v - full FPGA decoding chain test against the Python model
// Needs (generated by model/ldacs_ref.py --out <dir>): tb_cfg.vh, vit_in.mem, hw_expected.mem
// Random TVALID gaps and TREADY back-pressure are applied to test handshakes.
// ============================================================================
`timescale 1ns/1ps
module tb_decoder_top;
    `include "tb_cfg.vh"

    reg aclk = 0, aresetn = 0;
    always #5 aclk = ~aclk;   // 100 MHz

    reg  [7:0]  awaddr = 0, araddr = 0;
    reg         awvalid = 0, wvalid = 0, bready = 1, arvalid = 0, rready = 1;
    reg  [31:0] wdata = 0;
    wire        awready, wready, bvalid, arready, rvalid;
    wire [31:0] rdata;
    wire [1:0]  bresp, rresp;

    reg  [7:0]  s_tdata = 0;
    reg         s_tvalid = 0, s_tlast = 0;
    wire        s_tready;
    wire [7:0]  m_tdata;
    wire        m_tvalid, m_tlast;
    reg         m_tready = 0;
    wire [0:0]  m_tkeep;

    ldacs_decoder_top dut (
        .aclk(aclk), .aresetn(aresetn),
        .s_axi_ctrl_awaddr(awaddr), .s_axi_ctrl_awprot(3'd0), .s_axi_ctrl_awvalid(awvalid), .s_axi_ctrl_awready(awready),
        .s_axi_ctrl_wdata(wdata), .s_axi_ctrl_wstrb(4'hf), .s_axi_ctrl_wvalid(wvalid), .s_axi_ctrl_wready(wready),
        .s_axi_ctrl_bresp(bresp), .s_axi_ctrl_bvalid(bvalid), .s_axi_ctrl_bready(bready),
        .s_axi_ctrl_araddr(araddr), .s_axi_ctrl_arprot(3'd0), .s_axi_ctrl_arvalid(arvalid), .s_axi_ctrl_arready(arready),
        .s_axi_ctrl_rdata(rdata), .s_axi_ctrl_rresp(rresp), .s_axi_ctrl_rvalid(rvalid), .s_axi_ctrl_rready(rready),
        .s_axis_tdata(s_tdata), .s_axis_tvalid(s_tvalid), .s_axis_tready(s_tready), .s_axis_tlast(s_tlast),
        .m_axis_tdata(m_tdata), .m_axis_tvalid(m_tvalid), .m_axis_tready(m_tready), .m_axis_tlast(m_tlast),
        .m_axis_tkeep(m_tkeep)
    );

    task axil_write(input [7:0] a, input [31:0] d);
        begin
            @(posedge aclk); awaddr <= a; wdata <= d; awvalid <= 1; wvalid <= 1;
            wait (awready && wready); @(posedge aclk); awvalid <= 0; wvalid <= 0;
            wait (bvalid); @(posedge aclk);
        end
    endtask
    task axil_read(input [7:0] a, output [31:0] d);
        begin
            @(posedge aclk); araddr <= a; arvalid <= 1;
            wait (arready); @(posedge aclk); arvalid <= 0;
            wait (rvalid); d = rdata; @(posedge aclk);
        end
    endtask

    reg [7:0] vin [0:N_IN-1];
    reg [7:0] vexp [0:N_OUT-1];
    integer   in_i = 0, out_i = 0, errors = 0, frame = 0;
    // Firmware resets/configures the core for one measured frame per DMA run.
    integer   NFRAMES = 1;
    reg [31:0] rv;

    initial begin
        $readmemh("vit_in.mem", vin);
        $readmemh("hw_expected.mem", vexp);
        repeat (10) @(posedge aclk);
        aresetn = 1;
        axil_read(8'h24, rv);
        if (rv != 32'h46504C31) begin $display("FAIL: bad VERSION %h", rv); $finish; end
        axil_write(8'h08, CFG_RATE);
        axil_write(8'h0C, CFG_N_STEPS);
        axil_write(8'h10, CFG_NUM_CW);
        axil_write(8'h14, CFG_RS_N);
        axil_write(8'h4C, N_IN);
        axil_write(8'h28, CFG_TRACE);
    end

    // stream driver (two identical frames back to back)
    always @(posedge aclk) begin
        if (aresetn && frame < NFRAMES && $time > 2000) begin
            if (!s_tvalid || s_tready) begin
                if (s_tvalid && s_tready) begin
                    in_i = in_i + 1;
                    if (in_i == N_IN) begin in_i = 0; frame = frame + 1; end
                end
                if (frame < NFRAMES && ($random % 4) != 0) begin
                    s_tvalid <= 1; s_tdata <= vin[in_i]; s_tlast <= (in_i == N_IN-1);
                end else
                    s_tvalid <= 0;
            end
        end else if (frame >= NFRAMES)
            s_tvalid <= 0;
    end

    // output checker
    integer nframes_out = 0;
    always @(posedge aclk) begin
        m_tready <= ($random % 3) != 0;
        if (m_tvalid && m_tready) begin
            if (m_tdata !== vexp[out_i]) begin
                if (errors < 10) $display("MISMATCH frame %0d byte %0d: got %02x exp %02x", nframes_out, out_i, m_tdata, vexp[out_i]);
                errors = errors + 1;
            end
            if (m_tlast !== (out_i == N_OUT-1)) begin
                $display("TLAST error at byte %0d", out_i); errors = errors + 1;
            end
            out_i = out_i + 1;
            if (out_i == N_OUT) begin out_i = 0; nframes_out = nframes_out + 1; end
        end
    end

    initial begin : finish_blk
        reg [31:0] fr, corr, fail, vit_cycles, bdi_cycles, rs_cycles, pipe_cycles;
        wait (nframes_out == NFRAMES);
        repeat (5) @(posedge aclk);
        axil_read(8'h18, fr); axil_read(8'h1C, corr); axil_read(8'h20, fail);
        axil_read(8'h2C, vit_cycles); axil_read(8'h30, bdi_cycles);
        axil_read(8'h34, rs_cycles); axil_read(8'h38, pipe_cycles);
        $display("frames=%0d rs_corrected=%0d (exp %0d) rs_failed=%0d (exp %0d) sim_time=%0t",
                 fr, corr, EXP_CORR*NFRAMES, fail, EXP_FAIL*NFRAMES, $time);
        $display("measured cycles: viterbi=%0d block=%0d rs=%0d complete_pl=%0d",
                 vit_cycles, bdi_cycles, rs_cycles, pipe_cycles);
        if (fr != NFRAMES || corr != EXP_CORR*NFRAMES || fail != EXP_FAIL*NFRAMES) errors = errors + 1;
        if (pipe_cycles == 0) errors = errors + 1;
        if (CFG_TRACE == 0 && (vit_cycles==0 || bdi_cycles==0 || rs_cycles==0)) errors=errors+1;
        if (errors == 0) $display("TEST PASSED"); else $fatal(1,"TEST FAILED (%0d errors)", errors);
        $finish;
    end
    initial begin #2000000000; $fatal(1,"TIMEOUT"); end
endmodule
